frappe.query_reports["Store Sales Summary(AIO)"] = {
  __period_mode: "day",

  filters: [
    {
      fieldname: "from_date",
      label: __("From Date"),
      fieldtype: "Date",
      reqd: 1,
      read_only: 1,
      default: frappe.datetime.get_today()
    },
    {
      fieldname: "to_date",
      label: __("To Date"),
      fieldtype: "Date",
      reqd: 1,
      read_only: 0,
      default: frappe.datetime.get_today(),
      on_change: function() {
        const report_config = frappe.query_reports["Store Sales Summary(AIO)"];
        const report = frappe.query_report;

        let to_date = report.get_filter_value("to_date");
        if (!to_date) return;

        const mode = report_config.__period_mode || "day";

        // Helper functions
        const get_day_of_week = (date_str) => {
          const d = frappe.datetime.str_to_obj(date_str);
          return d.getDay();
        };

        const snap_to_monday = (date_str) => {
          const dow = get_day_of_week(date_str);
          if (dow === 1) return date_str;
          const days_to_monday = dow === 0 ? 6 : dow - 1;
          return frappe.datetime.add_days(date_str, -days_to_monday);
        };

        const snap_to_first = (date_str) => {
          const d = frappe.datetime.str_to_obj(date_str);
          const first = new Date(d.getFullYear(), d.getMonth(), 1);
          return frappe.datetime.obj_to_str(first);
        };

        const calc_from_date = (to_date, mode) => {
          if (mode === "day") {
            return to_date;
          } else if (mode === "week") {
            // From Monday of the week containing to_date
            return snap_to_monday(to_date);
          } else if (mode === "month") {
            // From 1st of the month containing to_date
            return snap_to_first(to_date);
          }
          return to_date;
        };

        // Calculate and set from_date based on mode
        const from_date = calc_from_date(to_date, mode);
        report.set_filter_value("from_date", from_date);

        report.refresh();
      }
    },
    {
      fieldname: "company",
      label: __("Company"),
      fieldtype: "MultiSelectList",
      get_data: function(txt) {
        return frappe.db.get_link_options("Company", txt);
      },
      on_change: function() {
        frappe.query_report.refresh();
      }
    }
  ],

  onload(report) {
    if (report.__period_btns_inited) return;
    report.__period_btns_inited = true;

    const report_config = frappe.query_reports["Store Sales Summary(AIO)"];

    let active_btn = null;

    const set_active = (btn) => {
      if (active_btn) {
        active_btn.removeClass("btn-primary").addClass("btn-default");
      }
      btn.removeClass("btn-default").addClass("btn-primary");
      active_btn = btn;
    };

    // Helper functions
    const get_day_of_week = (date_str) => {
      const d = frappe.datetime.str_to_obj(date_str);
      return d.getDay();
    };

    const snap_to_monday = (date_str) => {
      const dow = get_day_of_week(date_str);
      if (dow === 1) return date_str;
      const days_to_monday = dow === 0 ? 6 : dow - 1;
      return frappe.datetime.add_days(date_str, -days_to_monday);
    };

    const snap_to_first = (date_str) => {
      const d = frappe.datetime.str_to_obj(date_str);
      const first = new Date(d.getFullYear(), d.getMonth(), 1);
      return frappe.datetime.obj_to_str(first);
    };

    const calc_initial_range = (type) => {
      const today = frappe.datetime.get_today();
      let to_date, from_date;

      if (type === "day") {
        // Today only
        to_date = today;
        from_date = today;
      } else if (type === "week") {
        // This week: Monday to today
        to_date = today;
        from_date = snap_to_monday(today);
      } else if (type === "month") {
        // This month: 1st to today
        to_date = today;
        from_date = snap_to_first(today);
      }

      return { from_date, to_date };
    };

    const set_period_mode = (type, btn) => {
      report_config.__period_mode = type;

      const { from_date, to_date } = calc_initial_range(type);
      report.set_filter_value("from_date", from_date);
      report.set_filter_value("to_date", to_date);
      set_active(btn);
      report.refresh();
    };

    const make_btn = (label, type) => {
      const btn = $(
        `<button class="btn btn-default btn-sm" style="margin-right:6px; padding:4px 12px;">${__(label)}</button>`
      );
      btn.on("click", () => set_period_mode(type, btn));
      return btn;
    };

    const $btn_group = $(`<div class="d-flex align-items-center" style="margin-right:12px;"></div>`);
    const btn_day = make_btn("Day", "day");
    const btn_week = make_btn("Week", "week");
    const btn_month = make_btn("Month", "month");

    $btn_group.append(btn_day);
    $btn_group.append(btn_week);
    $btn_group.append(btn_month);

    const company_filter = report.get_filter("company");
    if (company_filter && company_filter.$wrapper && company_filter.$wrapper.length) {
      $btn_group.insertBefore(company_filter.$wrapper);
    } else {
      (report.page.page_form || report.page.wrapper).append($btn_group);
    }

    // Default to "Day" mode
    setTimeout(() => {
      set_period_mode("day", btn_day);
    }, 100);
  },

  // Remove the default Sr No column and clear row_no in total row
  after_datatable_render(datatable) {
    if (!datatable) return;

    // 1. Remove the auto-generated Sr No column (index 0, id "_rowIndex")
    if (datatable.datamanager && datatable.datamanager.columns) {
      const columns = datatable.datamanager.columns;
      if (columns.length > 0 && columns[0].id === "_rowIndex") {
        datatable.removeColumn(0);
      }
    }

    // 2. Clear row_no value in the total row (last row)
    // The total row is identified by having "Total" or empty shop field
    setTimeout(() => {
      const $wrapper = $(datatable.wrapper);
      const $rows = $wrapper.find(".dt-row");
      if ($rows.length > 0) {
        const $lastRow = $rows.last();
        // Check if it's a total row (usually has "Total" text or bold styling)
        const $firstCell = $lastRow.find(".dt-cell").first();
        const $secondCell = $lastRow.find(".dt-cell").eq(1);

        // If second cell contains "Total" or first cell has summed row_no, clear first cell
        const secondText = $secondCell.text().trim();
        if (secondText === "Total" || secondText === "") {
          $firstCell.find(".dt-cell__content").text("");
        }
      }
    }, 50);
  },

  formatter: function(value, row, column, data, default_formatter) {
    value = default_formatter(value, row, column, data);

    // Highlight negative values in red
    if (column.fieldtype === "Currency" && data && data[column.fieldname] < 0) {
      value = `<span style="color: red;">${value}</span>`;
    }

    return value;
  }
};
